Algorithm Saludo
  Define nombre As String <- "Ana";
  Write "Hola, " + nombre + '!';
  Write 'a' + 'b', " ", length('a' + 'b');
EndAlgorithm

Algorithm ConNumero
  Define edad As Integer <- 12;
  Write "Tienes " + toText(edad) + " años";
  Write "Tienes ", edad, " años";
EndAlgorithm
